import unittest

from solution import PanelState


class PanelStateTests(unittest.TestCase):
    def test_constructor_deep_copies_children(self):
        children = [{"name": "one", "data": {"values": [1, 2]}}]
        panel = PanelState("Title", children)
        children[0]["data"]["values"].append(3)
        children.append({"name": "two"})
        self.assertEqual(panel.snapshot(), {
            "title": "Title",
            "children": [{"name": "one", "data": {"values": [1, 2]}}],
        })

    def test_snapshot_is_deep_and_fresh(self):
        panel = PanelState("Title", [{"nested": [{"value": 1}]}])
        first = panel.snapshot()
        second = panel.snapshot()
        self.assertIsNot(first, second)
        self.assertIsNot(first["children"], second["children"])
        first["title"] = "changed"
        first["children"][0]["nested"][0]["value"] = 99
        first["children"].append({"extra": True})
        self.assertEqual(panel.snapshot(), {
            "title": "Title",
            "children": [{"nested": [{"value": 1}]}],
        })

    def test_append_deep_copies(self):
        panel = PanelState("T")
        child = {"items": [{"x": 1}]}
        panel.append(child)
        child["items"][0]["x"] = 8
        child["items"].append({"x": 2})
        self.assertEqual(panel.snapshot()["children"],
                         [{"items": [{"x": 1}]}])

    def test_empty_and_iterable_children(self):
        panel = PanelState("", ({"index": index} for index in range(2)))
        self.assertEqual(panel.snapshot(), {
            "title": "",
            "children": [{"index": 0}, {"index": 1}],
        })
        self.assertEqual(PanelState("none", None).snapshot()["children"], [])

    def test_validation(self):
        for title in (None, 3, True):
            with self.assertRaises(TypeError):
                PanelState(title)
        with self.assertRaises(TypeError):
            PanelState("T", [{"ok": 1}, ["not a dict"]])
        panel = PanelState("T")
        for child in (None, [], "dict", 1):
            with self.assertRaises(TypeError):
                panel.append(child)
        self.assertEqual(panel.snapshot()["children"], [])


if __name__ == "__main__":
    unittest.main()

